I.aggiungi({"Reset password": ["Password reset", "Réinitialisation du mot de passe"], "Come recuperare l’accesso, per l’utente e per l’amministratore.": ["How to regain access, for users and for the administrator.", "Comment retrouver l’accès, pour l’utilisateur et pour l’administrateur."], "Se sei un utente": ["If you are a user", "Si vous êtes utilisateur"], "Apri “Password dimenticata”": ["Open “Forgot password”", "Ouvrez « Mot de passe oublié »"], "Nella pagina di accesso, sotto il campo della password.": ["On the sign-in page, under the password field.", "Sur la page de connexion, sous le champ du mot de passe."], "Scrivi il tuo numero": ["Enter your number", "Saisissez votre numéro"], "Il prefisso +# è già inserito.": ["The +# prefix is already filled in.", "L’indicatif +# est déjà saisi."], "Usa lo stesso numero che hai dato all’amministratore.": ["Use the same number you gave the administrator.", "Utilisez le même numéro que vous avez donné à l’administrateur."], "Aspetta il codice su WhatsApp": ["Wait for the code on WhatsApp", "Attendez le code sur WhatsApp"], "Sono # cifre e valgono pochi minuti.": ["It has # digits and is valid for a few minutes.", "Il comporte # chiffres et est valable quelques minutes."], "Se non arriva, attendi un minuto e chiedilo di nuovo.": ["If it does not arrive, wait a minute and ask again.", "S’il n’arrive pas, attendez une minute et redemandez-le."], "Scegli la nuova password": ["Choose the new password", "Choisissez le nouveau mot de passe"], "Sempre di # cifre.": ["Always # digits.", "Toujours # chiffres."], "Poi accedi con il tuo nome e la nuova password.": ["Then sign in with your name and the new password.", "Connectez-vous ensuite avec votre nom et le nouveau mot de passe."], "Se non funziona": ["If it does not work", "Si cela ne marche pas"], "Il numero deve essere identico a quello registrato.": ["The number must be identical to the registered one.", "Le numéro doit être identique à celui enregistré."], "Se è diverso, o l’hai cambiato, il codice non parte e non ti viene detto il perché: scrivi all’amministratore.": ["If it is different, or you changed it, the code is not sent and you are not told why: write to the administrator.", "S’il est différent, ou si vous l’avez changé, le code n’est pas envoyé et on ne vous dit pas pourquoi : écrivez à l’administrateur."], "Dopo alcuni tentativi sbagliati l’account si blocca.": ["After a few wrong attempts the account is locked.", "Après quelques essais erronés le compte est bloqué."], "Solo l’amministratore può sbloccarlo.": ["Only the administrator can unlock it.", "Seul l’administrateur peut le débloquer."], "Un codice usato o scaduto non vale più: chiedine uno nuovo.": ["A used or expired code is no longer valid: ask for a new one.", "Un code utilisé ou expiré n’est plus valable : demandez-en un nouveau."], "Se sei l’amministratore": ["If you are the administrator", "Si vous êtes l’administrateur"], "Apri il pannello admin": ["Open the admin panel", "Ouvrez le panneau admin"], "Elenco degli utenti con stato: attivo o bloccato.": ["List of users with status: active or locked.", "Liste des utilisateurs avec leur état : actif ou bloqué."], "Sblocca l’account": ["Unlock the account", "Débloquez le compte"], "Azzera i tentativi sbagliati senza cambiare la password.": ["Resets the wrong attempts without changing the password.", "Remet à zéro les essais erronés sans changer le mot de passe."], "Genera una nuova password": ["Generate a new password", "Générez un nouveau mot de passe"], "Il sistema crea # cifre nuove e le mostra una sola volta.": ["The system creates # new digits and shows them only once.", "Le système crée # nouveaux chiffres et ne les montre qu’une fois."], "Comunicale all’utente.": ["Pass it on to the user.", "Communiquez-les à l’utilisateur."], "Correggi il numero di telefono": ["Correct the phone number", "Corrigez le numéro de téléphone"], "Se l’utente ha cambiato numero, aggiornalo: da quel momento vale per il reset.": ["If the user changed number, update it: from then on it is used for the reset.", "Si l’utilisateur a changé de numéro, mettez-le à jour : il sert alors pour la réinitialisation."], "Le password sono cifrate: nessuno può leggerle, nemmeno tu.": ["Passwords are encrypted: nobody can read them, not even you.", "Les mots de passe sont chiffrés : personne ne peut les lire, pas même vous."], "Si possono solo sostituire.": ["They can only be replaced.", "On peut seulement les remplacer."], "Torna alle stagioni": ["Back to seasons", "Retour aux saisons"], "Temperature mese per mese": ["Temperatures month by month", "Températures mois par mois"], "Guida al reset password": ["Password reset guide", "Guide de réinitialisation du mot de passe"]});
I.aggiungi({"Setup già fatto": ["Setup already done", "Configuration déjà faite"], "Hai già completato il Setup. Vuoi modificarlo?": ["You have already completed the Setup. Do you want to change it?", "Vous avez déjà terminé la configuration. Voulez-vous la modifier ?"], "Prezzi": ["Prices", "Prix"], "di mercato": ["market", "du marché"], "Modifica": ["Edit", "Modifier"], "Cancella": ["Delete", "Supprimer"], "Cancellare indirizzo, casa e prezzi? L’app tornerà ai valori medi e dovrai rifare il Setup.": ["Delete address, home and prices? The app will go back to average values and you will have to redo the Setup.", "Supprimer l’adresse, la maison et les prix ? L’application reviendra aux valeurs moyennes et il faudra refaire la configuration."], "Sì, cancella": ["Yes, delete", "Oui, supprimer"], "Annulla": ["Cancel", "Annuler"]});
